import json,re
from datetime import datetime, timezone
from collections import defaultdict
rows=[json.loads(l) for l in open('commits.jsonl') if l.strip()]
pat=re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$')
revpat=re.compile(r'^Revert "')
revert_ref=re.compile(r'^This reverts commit ([0-9a-f]{40})\.$')
named=set()
for r in rows:
    if revpat.match(r['message'].split('\n')[0]):
        for ln in r['message'].split('\n')[1:]:
            m=revert_ref.match(ln)
            if m: named.add(m.group(1))
inc=[]
for i,r in enumerate(rows):
    h=r['message'].split('\n')[0]
    m=pat.match(h)
    if not m: continue
    typ,scope,bang,summary=m.groups()
    if r['hash'] in named: continue
    scope=scope or 'general'
    if scope=='deps': scope='dependencies'
    if bang:
        sec='Breaking changes'
    elif typ=='fix' and scope!='internal':
        sec='Fixes'
    elif typ in ('feat','perf') and scope!='internal':
        sec='Features'
    else:
        continue
    s=summary[0].upper()+summary[1:]
    if s.endswith('.'): s=s[:-1]
    if typ=='perf' and not bang: s=s+' [perf]'
    refs=[]
    if typ=='fix':
        for ln in r['message'].split('\n')[1:]:
            mm=re.fullmatch(r'Fixes #(\d+)',ln)
            if mm: refs.append(int(mm.group(1)))
    inc.append(dict(i=i,h=r['hash'],typ=typ,scope=scope,sec=sec,summ=s,refs=refs,
                    dt=datetime.fromisoformat(r['date']),author=r['author'],email=r['email'],msg=r['message']))

# check time ties within sec+scope
for sec in set(e['sec'] for e in inc):
    seen=defaultdict(list)
    for e in inc:
        if e['sec']==sec: seen[(e['scope'],e['dt'])].append(e['h'][:7])
    for k,v in seen.items():
        if len(v)>1: print('TIE',sec,k,v)

# group
groups=defaultdict(list)
for e in inc:
    groups[(e['sec'],e['scope'],e['summ'])].append(e)
entries=[]
for (sec,scope,summ),cs in groups.items():
    cs.sort(key=lambda x:(-x['dt'].timestamp(), x['h']))
    refs=[]
    if sec=='Fixes':
        for c in cs:
            for n in c['refs']:
                if n not in refs: refs.append(n)
    entries.append(dict(sec=sec,scope=scope,summ=summ,cs=cs,refs=refs,newest=cs[0]['dt']))
print('groups',len(groups),'entries',len(entries))
for e in sorted(entries,key=lambda x:(x['sec'],x['scope'],-x['newest'].timestamp())):
    if len(e['cs'])>1:
        print('MERGED',e['sec'],e['scope'],repr(e['summ']),[(c['h'][:7],c['dt].isoformat() if False else c['dt'].isoformat()) for c in e['cs']],e['refs'])

# final lines
sec_order=['Breaking changes','Features','Fixes']
out=[]
out.append('# Release 4.2.0\n')
for sec in sec_order:
    ss=sorted([e for e in entries if e['sec']==sec],key=lambda x:(x['scope'],-x['newest'].timestamp()))
    if not ss: continue
    out.append('## '+sec+'\n')
    for e in ss:
        prefix=f"- **{e['scope']}:** "
        refs=''.join(f' (#{n})' for n in e['refs'])
        hashes=', '.join(c['h'][:7] for c in e['cs'])
        suffix=f" ({hashes})"
        fixed=len(prefix)+len(refs)+len(suffix)
        summ=e['summ']
        if fixed+len(summ)>100:
            avail=100-fixed-1
            summ=summ[:avail].rstrip(' ')+'\u2026'
        line=prefix+summ+refs+suffix
        out.append(line)
    out.append('')
# remove trailing blank line for section separation; build file with exact newline semantics later
for l in out:
    if len(l)>100: print('LONG',len(l),repr(l))
print('=== candidate file ===')
print('\n'.join(out))
