    es=re.findall(r'<([^<>]+)>',line)
    if es:
        n=line.split('<',1)[0].strip()
        for e in es: mailmap[e]=n
tr=re.compile(r'^Co-authored-by: (.+) <([^<>]+)>$')
inc=[]
for r in rows:
