    elif typ=='fix' and scope!='internal': sec='Fixes'
    elif typ in ('feat','perf') and scope!='internal': sec='Features'
    else: continue
    s=summary[0].upper()+summary[1:]
    if s.endswith('.'): s=s[:-1]
    if typ=='perf' and not bang: s+=' [perf]'
    refs=[]
    if typ=='fix':
        for ln in r['message'].split('\n')[1:]:
            mm=re.fullmatch(r'Fixes #(\d+)',ln)
            if mm: refs.append(int(mm.group(1)))
    inc.append(dict(h=r['hash'],typ=typ,scope=scope,sec=sec,summ=s,refs=refs,dt=datetime.fromisoformat(r['date']).astimezone(timezone.utc),author=r['author'],email=r['email'],msg=r['message']))
g=defaultdict(list)
for e in inc: g[(e['sec'],e['scope'],e['summ'])].append(e)
ents=[]
for (sec,scope,summ),cs in g.items():
    cs.sort(key=lambda x:(-x['dt'].timestamp(),x['h']))
    refs=[]
    if sec=='Fixes':
        for c in cs:
            for n in c['refs']:
                if n not in refs: refs.append(n)
    ents.append(dict(sec=sec,scope=scope,summ=summ,cs=cs,refs=refs,newest=cs[0]['dt']))
credit=Counter(); authors=set()
for e in inc:
    ps=set(); a=mailmap.get(e['email'],e['author'])
    if not a.endswith('[bot]'): ps.add(a); authors.add(a)
    for ln in e['msg'].split('\n')[1:]:
        m=tr.match(ln)
        if m:
            c=mailmap.get(m.group(2),m.group(1))
            if not c.endswith('[bot]'): ps.add(c)
    credit.update(ps)
