        fixed=len(pre)+len(rf)+len(suf); sm=e['summ']
        if fixed+len(sm)>100:
            sm=sm[:100-fixed-1].rstrip(' ')+'\u2026'
        lines.append(pre+sm+rf+suf)
    lines.append('')
con=sorted(((p,credit[p]) for p in authors),key=lambda kv:(-kv[1],kv[0]))
lines += ['## Contributors','']+[f'- {p} ({n})' for p,n in con]
expected='\n'.join(lines)+'\n'
actual=open('RELEASE_NOTES.md',encoding='utf-8').read()
print('MATCH', expected==actual, len(expected), len(actual))
if expected!=actual:
    import difflib
    print(''.join(difflib.unified_diff(expected.splitlines(True),actual.splitlines(True))))
